from .interface_4g import Interface4GLegacy
from .facade import AdminConnection

from taf.internal.robot_typecasts import time_to_seconds, to_boolean
from taf.internal.aliasing import LookupHandler

# For the deprecated reconnect_with_default_on_failure in connect_to
from ute_common_admin.exception import AdminApiConnectionClosedException

import logging
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class admin(Interface4GLegacy):
    """
    Usage example:
        >>> from taf.gnb.oam.coam.admin import admin
        >>> api = admin()
        >>> connection = api.connect_to()
        >>> result = connection.get_bts_info()
        >>> result["id"]["internal"]
        "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1"

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler = LookupHandler("connection", AdminConnection)

    def __init__(self):
        self.lookup_handler.store = self.store

    def connect_to(self,
                   bts_host="192.168.255.1",
                   bts_port=443,
                   username="Nemuadmin",
                   password="nemuuser",
                   use_ssl=True,
                   update_interval=5000,
                   admin_api_log_dir="",
                   name="default",
                   bundle_path=None,
                   reconnect_with_default_on_failure=False,
                   release="admin22r3",
                   ):
        """
        Connect to Node B.

        :param str bts_host: BTS IP address.
        :param int bts_port: AdminAPI port.
        :param str username: AdminAPI username.
        :param str password: AdminAPI password.
        :param bool use_ssl: use SSL.
        :param int update_interval: The minimum updates interval in [ms].
        :param str admin_api_log_dir: AdminAPI log dir
        :param str name: (Optional) Name of returned connection. It not provided, this connection becomes default.
        :param str bundle_path: (Optional) Path to alternative or knife bundle.js provided by ADMIN
        :param bool reconnect_with_default_on_failure: (*DEPRECATED*, Optional), default False, If enabled, and connection attempt
            fails, we will try to reconnect with default value of bts_host and bts_port (192.168.255.1 and 443).
        :param str release: Name of coam admin interface version. Set to the newest by default. Available releases:
            admin19b, admin20a, admin20b, admin21a. If user expects from the library that interface is stable, always
            specify release version in your code.
        :return: Instance object of AdminConnection
        """
        # We don't check truthiness, but rather whether the value given was the
        # default, hence 'is not False'
        if reconnect_with_default_on_failure is not False:
            logger.critical("DEPRECATED: \"reconnect_with_default_on_failure\" "
                            "argument of taf.gnb.aom.coam.admin \"Connect To\" "
                            "keyword is deprecated, and will be removed soon. ")

        reconnect = to_boolean(reconnect_with_default_on_failure)
        logger.warn("""[DEPRECATION WARNING] Please be informed that for testing SBTS21B onwards taf.sbts.oam.coam.admin is recommended\n
                    Please start migration.\n
                    https://taf-sbts-oam-coam-admin.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface.html""")

        try:
            connection = AdminConnection(
                bts_host=bts_host,
                bts_port=bts_port,
                username=username,
                password=password,
                use_ssl=to_boolean(use_ssl),
                update_interval=update_interval,
                admin_api_log_dir=admin_api_log_dir,
                name=name,
                bundle_path=bundle_path,
                release=release,
            )
        except AdminApiConnectionClosedException:
            if not reconnect:
                raise

            # XXX: IMPORTANT! some reconnect logic is also in
            # facade.AdminConnection - Remove it from there too.
            logger.critical("DEPRECATED: Cannot connect to BTS via admin using "
                            "given parameters. Please adjust \"bts_host\" and "
                            "\"bts_port\" values given to \"Connect To\". The "
                            "library will now try to reconnect using default "
                            "values of these parameters (192.168.255.1:443), "
                            "since you've passed \"True\" to "
                            "\"reconnect_with_default_on_failure\". This "
                            "fallback functionality is deprecated and will be "
                            "disabled & removed soon.")
            logger.exception("Reconnection issued due to the following "
                             "exception:")

            connection = AdminConnection(
                bts_host='192.168.255.1',
                bts_port=443,
                username=username,
                password=password,
                use_ssl=to_boolean(use_ssl),
                update_interval=update_interval,
                admin_api_log_dir=admin_api_log_dir,
                name=name,
                bundle_path=bundle_path,
                release=release,
            )

        self.store.add(connection, name)
        return connection

    @lookup_handler.implicit_lookup
    def get_bts_info(self, timeout=10, connection=None):
        """
        Keyword for getting BTS general information from Node B

        :param Union[int,str] timeout: Keyword execution timeout.
        :param AdminConnection connection: AdminConnection object or if used, string name alias
        :return: Dictionary with data. More details (content of requestMessage is returned data):
                 https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-getBtsInformation.html
        """
        return connection.get_bts_info(timeout=time_to_seconds(timeout, round_to=0))

